css:
/* Аркуш А4 із змінними з Jinja */
@page { size: A4; margin: 0; }

.sheet {
  --cols: 3;
  --label-w: 70mm;
  --label-h: 36mm;
  --gap: 4mm;
  --page-margin: 8mm;
  --qr: 18mm;
  --font: 11px;

  padding: var(--page-margin);
  display: grid;
  grid-template-columns: repeat(var(--cols), var(--label-w));
  grid-auto-rows: var(--label-h);
  gap: var(--gap);
  justify-content: start;   /* щоб не розтягувало останній ряд */
  align-content: start;
  font-family: "DejaVu Sans", "Liberation Sans", Arial, Helvetica, sans-serif;
  color: #0f172a;
  font-size: var(--font);
  line-height: 1.2;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* Одна етикетка */
.lbl {
  box-sizing: border-box;
  border: 0.3mm solid #e2e8f0;
  border-radius: 2mm;
  padding: 2.5mm 3mm;
  background: #fff;
  display: grid;
  grid-template-rows: auto 1fr;
  overflow: hidden;
}

/* Порожній заповнювач (щоб сітка була рівна) */
.lbl-empty { border-color: transparent; visibility: hidden; }

/* Верхня частина: Назва + QR */
.lbl-top {
  display: grid;
  grid-template-columns: 1fr var(--qr);
  gap: 2mm;
  align-items: start;
}
.lbl-title {
  font-weight: 800;
  font-size: calc(var(--font) + 1px);
  line-height: 1.15;
  max-height: calc(var(--qr) + 4mm); /* щоб назва не вибивала QR */
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 3;     /* 2–3 рядки залежно від висоти ярлика */
  -webkit-box-orient: vertical;
  word-break: break-word;
}
.lbl-qr img {
  width: var(--qr);
  height: var(--qr);
  display: block;
  border: 0.3mm solid #e2e8f0;
  border-radius: 1mm;
  padding: 1mm;
  background: #fff;
}

/* Тіло: рядки з даними */
.lbl-body { margin-top: 1.5mm; display: grid; gap: 1.2mm; }
.lbl-row { display: grid; grid-template-columns: auto 1fr; gap: 1mm; align-items: baseline; }
.lbl-key { font-weight: 700; color: #334155; white-space: nowrap; }
.lbl-val { color: #0f172a; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.lbl-id .lbl-val { font-family: "Liberation Mono", "DejaVu Sans Mono", Consolas, monospace; }

/* Для дійсно маленьких ярликів можна зменшити відступи */
@media print {
  .sheet { break-inside: avoid; }
}

html:
{# ------- helpers ------- #}
{%- set cols = (doc.columns or 3) | int -%}
{%- set label_w = (doc.label_width_mm or 70) -%}
{%- set label_h = (doc.label_height_mm or 36) -%}
{%- set gap = (doc.gap_mm or 4) -%}
{%- set margin = (doc.page_margin_mm or 8) -%}
{%- set font_px = (doc.font_px or 11) -%}
{%- set qr_mm = (doc.qr_size_mm or 18) -%}
{%- set show_inv = (doc.show_inventory_no or 0) -%}
{%- set show_sn = (doc.show_serial_no or 0) -%}

{%- set base_url = frappe.utils.get_url() -%}
{%- macro asset_doc(item) -%}
  {%- set a = frappe.get_doc("oiAsset", item.asset) -%}
  {{- a -}}
{%- endmacro -%}

{%- macro label_block(item) -%}
  {# отримаємо актив #}
  {%- set a = frappe.get_doc("oiAsset", item.asset) -%}
  {%- set title = item.override_title or a.asset_name or a.name -%}
  {%- set inv = item.override_inventory_no or a.inventory_no -%}
  {%- set sn = item.override_serial_no or a.serial_no -%}
  {%- set url = frappe.utils.get_url_to_form("oiAsset", a.name) -%}

  <div class="lbl">
    <div class="lbl-top">
      <div class="lbl-title" title="{{ title }}">{{ title }}</div>
      <div class="lbl-qr">
        <img src="https://quickchart.io/qr?text={{ (url|urlencode) }}&margin=0" alt="QR" />
      </div>
    </div>
    <div class="lbl-body">
      {%- if show_inv -%}
        <div class="lbl-row">
          <span class="lbl-key">Інв. №:</span>
          <span class="lbl-val">{{ inv or "—" }}</span>
        </div>
      {%- endif -%}
      {%- if show_sn -%}
        <div class="lbl-row">
          <span class="lbl-key">Сер. №:</span>
          <span class="lbl-val">{{ sn or "—" }}</span>
        </div>
      {%- endif -%}
      <div class="lbl-row lbl-id">
        <span class="lbl-key">ID:</span>
        <span class="lbl-val">{{ a.name }}</span>
      </div>
    </div>
  </div>
{%- endmacro -%}

{# ------- sheet root with CSS variables ------- #}
<div class="sheet"
     style="
      --cols: {{ cols }};
      --label-w: {{ label_w }}mm;
      --label-h: {{ label_h }}mm;
      --gap: {{ gap }}mm;
      --page-margin: {{ margin }}mm;
      --qr: {{ qr_mm }}mm;
      --font: {{ font_px }}px;
     ">

  {%- for it in doc.items or [] -%}
    {%- set copies = (it.copies or 1) | int -%}
    {%- for i in range(copies) -%}
      {{ label_block(it) }}
    {%- endfor -%}
  {%- endfor -%}

  {# опційно: вирівняти сітку, додавши пусті плейсхолдери до кратності колонок #}
  {%- set total = (doc.items or []) | sum(attribute="copies") if doc.items else 0 -%}
  {%- if total and (total % cols) != 0 -%}
    {%- for i in range(cols - (total % cols)) -%}
      <div class="lbl lbl-empty"></div>
    {%- endfor -%}
  {%- endif -%}
</div>
